package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.concurrent.atomic.AtomicLong;
public class SubmittedExpiryTest {
 static final long HOUR=3600000L;
 @Test public void expiresOnlyOldSubmittedEntriesWithoutAnyNasRequest()throws Exception{long now=100*HOUR;TorrentRulesTest.Memory store=new TorrentRulesTest.Memory();store.put("prepared:user",new JSONArray().put(new JSONObject().put("list_id","old").put("submitted",true).put("submitted_at",now-25*HOUR)).put(new JSONObject().put("list_id","recent").put("submitted",true).put("submitted_at",now-HOUR)).put(new JSONObject().put("list_id","draft").put("submitted",false).put("submitted_at",now-25*HOUR)).toString());TorrentRulesTest.Fake nas=new TorrentRulesTest.Fake(store);DownloadStation ds=new DownloadStation(nas,store,"user",()->now);assertFalse(ds.prepared.containsKey("old"));assertTrue(ds.prepared.containsKey("recent"));assertTrue(ds.prepared.containsKey("draft"));assertTrue(nas.calls.isEmpty());assertFalse(store.get("prepared:user","").contains("old"));}
 @Test public void legacyUnknownDateGetsOneDayGraceAndNeverRestarts()throws Exception{AtomicLong now=new AtomicLong(100*HOUR);TorrentRulesTest.Memory store=new TorrentRulesTest.Memory();store.put("prepared:user","[{\"list_id\":\"legacy\",\"submitted\":true}]");TorrentRulesTest.Fake nas=new TorrentRulesTest.Fake(store);DownloadStation ds=new DownloadStation(nas,store,"user",now::get);assertEquals(now.get(),ds.prepared.get("legacy").getLong("submitted_at"));now.addAndGet(24*HOUR);ds.pruneSubmitted();assertTrue(ds.prepared.containsKey("legacy"));now.addAndGet(HOUR);ds.pruneSubmitted();assertTrue(ds.prepared.isEmpty());assertTrue(nas.calls.isEmpty());}
 @Test public void uncertainStartPersistsTimestampBeforeNetworkCall()throws Exception{TorrentRulesTest.Memory store=new TorrentRulesTest.Memory();TorrentRulesTest.Fake nas=new TorrentRulesTest.Fake(store);DownloadStation ds=new DownloadStation(nas,store,"user",()->123456L);ds.prepare("https://example.org/a.torrent",null,null,"video");nas.uncertain=true;try{ds.start("preview-1",java.util.Set.of(0));fail();}catch(java.io.IOException expected){}assertEquals(123456L,new JSONArray(store.get("prepared:user","[]")).getJSONObject(0).getLong("submitted_at"));}
 @Test public void expiredSubmissionAlsoClearsOnlyItsOwnSelection()throws Exception{long now=100*HOUR;TorrentRulesTest.Memory store=new TorrentRulesTest.Memory();JSONArray records=new JSONArray().put(new JSONObject().put("list_id","old").put("submitted",true).put("submitted_at",now-25*HOUR)).put(new JSONObject().put("list_id","recent").put("submitted",true).put("submitted_at",now-HOUR)).put(new JSONObject().put("list_id","draft").put("submitted",false).put("submitted_at",now-25*HOUR));store.put("prepared:user",records.toString());for(String id:java.util.List.of("old","recent","draft"))store.put("torrent_choice:user:"+id,"[0,1]");TorrentRulesTest.Fake nas=new TorrentRulesTest.Fake(store);DownloadStation ds=new DownloadStation(nas,store,"user",()->now);assertFalse(ds.prepared.containsKey("old"));assertEquals("",store.get("torrent_choice:user:old","missing"));assertEquals("[0,1]",store.get("torrent_choice:user:recent",""));assertEquals("[0,1]",store.get("torrent_choice:user:draft",""));assertTrue(nas.calls.isEmpty());}
}
